export const BODY: string = "\n<p>عرض بيانات صورة وصفية يبدو تقنيًا، لكنه يستغرق أقل من دقيقة: تفتح صورة في عارض وتقرأ التقرير وتقرر إن كان شيء مما بداخلها يجب أن يبقى خاصًا.</p>\n<p>يمر هذا الدليل بكل خطوة مع عارض البيانات الوصفية المجاني: يعمل في متصفحك ولا يطلب حسابًا ولا يرفع صورك أبدًا.</p>\n<p>في النهاية ستعرف كيف تجد إحداثيات GPS وتقرأ ضبط الكاميرا وتصدّر تقرير JSON وتتحقق من أن ملفًا نظيفًا نظيف فعلًا.</p>\n<h2 id=\"what-you-need\">ما تحتاجه قبل أن تبدأ</h2>\n<p>تحتاج ملف الصورة نفسه، محفوظًا على جهازك: الملف الأصلي من معرضك أو بطاقة الكاميرا يحمل أكبر قدر من البيانات الوصفية. وصورة منزلة من WhatsApp أو إنستغرام أو فيسبوك موضوع اختبار سيئ: تلك الخدمات تزيل ترويسات EXIF وGPS عند الرفع، فسيجد العارض قليلًا أو لا شيء.</p>\n<p>لقطات الشاشة سيئة أيضًا للاختبار: حافظة نظام تشغيلك تمرر بكسلات خام، لا ملف الكاميرا الأصلي، فاللقطات الملصوقة تُظهر فقط معلومات الحاوية الأساسية. واستخدم ملف JPG أو PNG أو WebP أو HEIC أو GIF أو BMP أو SVG حتى 20 MB: هذا يغطي صور هاتف بدقة كاملة وJPEG كاميرات DSLR وتصديرات PNG مفصلة.</p>\n<p>افتح العارض في أي متصفح حديث: Chrome وFirefox وSafari وEdge تعمل، على الحاسوب والهاتف.</p>\n<h2 id=\"step-1-open-the-viewer\">الخطوة 1: افتح العارض</h2>\n<p>اذهب إلى صفحة <a href=\"/ar/arid-bayanat-as-sura/\">عارض البيانات الوصفية</a>: سترى منطقة رفع وشرحًا موجزًا لما تفعله الأداة.</p>\n<p>لا شاشة تسجيل دخول ولا جدار دفع: الأداة مجانية، وتستطيع مراجعة صور بقدر ما تريد، واحدة في كل مرة. وإذا كنت على الهاتف، افتح الصفحة في Safari على iOS أو Chrome: يتكيف التصميم، وتستطيع اختيار صورة مباشرة من معرضك.</p>\n<p>احفظ الصفحة في المفضلة إذا راجعت صورًا كثيرًا: المصورون والبائعون والآباء غالبًا يستخدمونها قبل كل نشر، فوجودها في متناول اليد يساعد.</p>\n<h2 id=\"step-2-upload-your-image\">الخطوة 2: ارفع صورتك</h2>\n<p>اسحب صورتك إلى منطقة الرفع، أو انقر عليها لاختيار ملف من جهازك: يُحلل الملف فورًا، هناك في متصفحك.</p>\n<p>ويمكنك أيضًا لصق صورة بـCtrl+V على Windows أو Cmd+V على Mac: اللصق عملي لصورة موجودة في حافظتك، لكن تذكر أن صور الحافظة لا تحمل ترويسات كاميرا. ويحدث التحليل محليًا، بتحليل بايتات عبر File ArrayBuffer: صفر بايت يغادر حاسوبك أو هاتفك، وهو بالضبط معنى أداة خصوصية.</p>\n<p>وإذا زاد وزن الملف عن 20 MB، فلن يعمل الرفع: اضغطه أولًا بـ<a href=\"/ar/\">ضاغط الصور</a> ثم راجع النسخة الأصغر. وفي لحظة يظهر شريط الملخص: تلك هي نتيجتك الأولى، وتجيب بالفعل على أهم سؤال: هل يحمل هذا الملف بيانات حساسة؟</p>\n<h2 id=\"step-3-read-the-summary\">الخطوة 3: اقرأ الملخص وإشعار الخصوصية</h2>\n<p>يُظهر شريط الملخص الصيغة المكتشفة والأبعاد بالبكسلات وحجم الملف: ويشير أيضًا إلى إن وُجدت أنواع وسوم بيانات وصفية حساسة.</p>\n<p>اقرأ الصيغة أولًا: يفحص العارض البايتات السحرية الثنائية الحقيقية بدل الثقة باسم الملف، فـPNG معاد تسميته بامتداد .jpg ما زال يُبلغ عنه كـPNG. ثم اقرأ إشعار مخاطر الخصوصية: إذا وُجدت وسوم حساسة، يقول الإشعار ذلك بوضوح. وإذا لم يُوجد شيء حساس، يقول ذلك أيضًا.</p>\n<p>ملخص نظيف لا يعني دائمًا أن الملف أصلي: صورة نظيفة من تطبيق مراسلة تُظهر أيضًا ملخصًا نظيفًا، لأن بياناتها الوصفية أُزيلت مسبقًا. وقارن الملخص بما تتوقعه: JPEG من DSLR يجب أن يُظهر بيانات كاميرا. ولقطة شاشة يجب أن تُظهر تقريبًا لا شيء. وإذا لم يتطابقا، عُولج الملف في نقطة ما على الطريق.</p>\n<h2 id=\"step-4-check-gps\">الخطوة 4: ابحث عن تنبيه موقع GPS</h2>\n<p>إحداثيات GPS هي أول ما تراجعه، لأنها أكثر حقل حساسية قد تحمله صورة: مرّر إلى منطقة الإشعار، فوق جدول الخصائص مباشرة.</p>\n<p>إذا وُجدت وسوم GPSIFD، يظهر إشعار كهرماني يقول GPS Location Coordinates Detected: يُظهر خط العرض وخط الطول الدقيقين مفكوكين بالفعل، بصيغة عشرية. ويمكن أن يشير هذان الرقمان إلى منزل أو مدرسة أو عمل أو المكان الدقيق الذي التُقطت فيه الصورة: عاملهما كخاصين حتى تقرر خلاف ذلك.</p>\n<p>يقدم مربع الإشعار أيضًا قفزة بنقرة واحدة إلى <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a>: إذا نويت مشاركة الصورة، اتبع ذلك الرابط وأزل الوسوم أولًا. وإذا لم يظهر أي تنبيه GPS، فالصورة لا تحمل بيانات موقع: تلك هي النتيجة التي تريدها قبل نشر أي صورة التُقطت في المنزل أو قرب أطفالك.</p>\n<h2 id=\"step-5-read-the-table\">الخطوة 5: اقرأ جدول البيانات الوصفية</h2>\n<p>تحت الإشعار جدول البيانات الوصفية المستخرجة: الإدخالات مجمعة لتستطيع مراجعتها دون قراءة كل سطر.</p>\n<p>تحفظ مجموعة الكاميرا العلامة والموديل والعدسة والبرنامج. وتحفظ مجموعة EXIF سرعة الغالق والفتحة وISO والبعد البؤري والفلاش ووضع القياس. وتحفظ مجموعة GPS خط العرض وخط الطول والارتفاع عندما تكون موجودة. وتحفظ مجموعة مقاطع PNG أو WebP مقاطع IHDR وpHYs والنص وعلامات VP8X.</p>\n<p>تحفظ مجموعة معلومات الملف الصيغة والأبعاد والحجم: بيانات عن الملف نفسه، لا عن الكاميرا. وتحمل الإدخالات الحساسة وسم Privacy Tag كهرمانيًا: ابحث عن إحداثيات GPS وطوابع زمنية دقيقة للالتقاط وأسماء مصورين أو فنانين وأرقام تسلسلية للكاميرا وسلاسل بها اسم جهازك.</p>\n<p>خذ وقتك مع الطابع الزمني: التاريخ والوقت الدقيقان اللذان التُقطت فيهما صورة قد يكشفان روتينًا، مثل متى يكون منزل فارغًا أو متى يخرج طفل من المدرسة.</p>\n<h2 id=\"step-6-export-json\">الخطوة 6: انسخ تقرير JSON أو صدّره</h2>\n<p>إذا احتجت سجلًا لما احتواه الملف، صدّره: انقر نسخ JSON في شريط الملخص لنقل التقرير المنظم الكامل إلى حافظتك.</p>\n<p>انقر تصدير JSON لتنزيل ملف باسم صورتك ولاحقة _metadata: إنه تقرير JSON نظيف تستطيع حفظه أو إرفاقه بتذكرة أو مقارنته لاحقًا. ويستخدم المطورون هذه التقارير لتصحيح سير عمل الصور: إذا اختفى حقل بين خطوتي معالجة، تُظهر تقارير JSON بالضبط أين فُقد.</p>\n<p>ويستخدمها المصورون لحفظ وصفات تعريض: يحتفظ JSON بـISO والفتحة وسرعة الغالق للقطة تستحق التكرار. ولشرح أعمق لما يعنيه كل حقل، اقرأ <a href=\"/ar/blog/bayanat-exif-mashruha/\">بيانات EXIF موضحة: ما تكشفه صورك</a>. ولرؤية الأداة كاملة، اقرأ <a href=\"/ar/blog/dalil-arid-bayanat-as-suwar/\">دليل عارض بيانات الصور الكامل</a>.</p>\n<h2 id=\"step-7-verify-clean\">الخطوة 7: تحقق من ملف نظيف</h2>\n<p>بعد إزالة البيانات الوصفية من صورة، اسحب الملف النظيف مجددًا إلى العارض: هذه المراجعة الثانية تثبت أن التنظيف نجح.</p>\n<p>إذا نجح التنظيف، يؤكد إشعار أخضر أنه لم تُكتشف وسوم EXIF أو GPS أو كاميرا مخفية: لا يظهر أي تنبيه GPS. وإذا بقيت وسوم، يُظهر الجدول بالضبط أيها نجا: الناجون الشائعون مقاطع نص PNG وتعليقات JPEG، التي يتخطاها بعض المنظفات.</p>\n<p>وعند ظهور بقايا، نظف الملف مجددًا بـFull Canvas Re-encode في أداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a>: يعيد بناء البكسلات من الصفر ويزيل كل مقطع موروث. واجعل هذا عادة تمريرتين مع الصور الحساسة: راجع ونظف وأعد المراجعة. والتمريرة الثانية تستغرق ثوانٍ وتزيل كل شك.</p>\n<h2 id=\"viewing-on-mobile\">عرض البيانات الوصفية على الهاتف</h2>\n<p>معظم الصور تعيش على الهاتف، والمراجعة تهم أكثر قبل النشر مباشرة: افتح العارض في Safari على iOS أو Chrome واختر صورة من معرضك.</p>\n<p>يظهر الملخص وتنبيه GPS والجدول المجمع مثل الحاسوب تمامًا: نسخ JSON وإزالة البيانات الوصفية تعملان بالتساوي. وراجع الصورة قبل فتح تطبيق التواصل الاجتماعي، لا بعده: بمجرد نشر الصورة، يستطيع أي شخص تنزيلها وقراءة ما ما زالت تحمله بداخلها.</p>\n<p>وإذا وجدت بيانات GPS، أزلها على الهاتف قبل مشاركتها: تعمل أداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a> في متصفح الهاتف، فالسير كله يناسب جيبك.</p>\n<h2 id=\"reading-camera-settings\">كيف تقرأ ضبط الكاميرا في التقرير</h2>\n<p>يروي ضبط الكاميرا قصة كيف صُنعت صورة: كل حقل له معنى واضح بمجرد أن تعرف ما تبحث عنه.</p>\n<p>ISO هو حساسية المستشعر: ISO منخفض يعني مشهدًا ساطعًا أو حاملًا ثلاثيًا؛ وISO مرتفع يعني مشهدًا داكنًا وضجيجًا أكثر غالبًا. والفتحة، المعروضة كرقم F، هي كم فُتحت العدسة: رقم F صغير يعني فتحة واسعة وخلفية ضبابية؛ وكبير يعني مشهدًا عميقًا وحادًا.</p>\n<p>سرعة الغالق هي كم بقي المستشعر معرضًا: السرعات السريعة تجمد الحركة، والبطيئة تضببها. ويعرضها العارض ككسر من ثانية أو بالثواني. والبعد البؤري هو زوم العدسة لحظة الالتقاط: أبعاد قصيرة تعني عرضًا واسعًا؛ وطويلة تعني عرضًا مكبرًا.</p>\n<p>تخبرك حالة الفلاش إن أُطلق الفلاش: ويخبرك وضع القياس كيف قاست الكاميرا الضوء. ومعًا، تتيح هذه الحقول لمصور آخر إعادة إنشاء اللقطة.</p>\n<h2 id=\"troubleshooting\">حل المشاكل: عندما يخرج التقرير فارغًا</h2>\n<p>تقرير فارغ غالبًا له سبب بسيط: راجع القائمة التالية قبل افتراض أن العارض مكسور.</p>\n<p>وإذا توقعت بيانات كاميرا ولم تحصل على أي منها، جرّب أصلًا حديثًا من المعرض: هذا يخبرك إن كانت المشكلة الملف أم العارض. وإذا لم يُظهر الأصل أيضًا شيئًا، راجع ضبط تطبيق الكاميرا: بعض الهواتف تتيح تعطيل تسجيل الموقع، ما يزيل وسوم GPS من المصدر.</p>\n<ul>\n<li>جاءت الصورة من WhatsApp أو إنستغرام أو فيسبوك: تزيل هذه الخدمات EXIF وGPS عند الرفع، فيصل الملف نظيفًا.</li>\n<li>لصقت لقطة شاشة: تمرر الحافظات بكسلات خام، فالصور الملصوقة لا تحمل أي ترويسة كاميرا.</li>\n<li>الملف HEIC أو GIF أو BMP أو SVG: يبلغ العارض عن معلومات الحاوية والأبعاد، لكن مقاطع EXIF الثنائية الكاملة تُستخرج فقط في JPEG وPNG وWebP.</li>\n<li>عُدلت الصورة وأُعيد تصديرها: كثير من المحررين يزيل EXIF عند التصدير، إلا إذا طلبت منهم الاحتفاظ به.</li>\n<li>الملف كان نظيفًا أصلًا: صورة نظيفة بأداة إزالة البيانات الوصفية ستُظهر الإشعار الأخضر بعدم وجود وسوم، وهو النتيجة الصحيحة.</li>\n</ul>\n<h2 id=\"common-mistakes\">أخطاء شائعة يجب تجنبها</h2>\n<p>أكثر خطأ شيوعًا مراجعة الملف الخطأ: يراجع الناس نسخة نشروها بالفعل ولا يرون شيئًا ويفترضون أن الأصل نظيف أيضًا: راجع دائمًا الملف الذي أنت على وشك مشاركته.</p>\n<p>خطأ آخر الثقة باسم الملف: ملف .jpg قد يكون حقًا PNG، ويبلغ العارض عن الصيغة الحقيقية من البايتات السحرية. اقرأ الملخص، لا الامتداد. وخطأ ثالث تخطي المراجعة الثانية: يبدو التنظيف مكتملًا عندما يظهر التنزيل، لكن مراجعة جديدة فقط تثبت أن الوسوم اختفت.</p>\n<p>خطأ رابع نسيان الطابع الزمني: يبحث الناس عن GPS ويتجاهلون وقت الالتقاط، لكن طابعًا زمنيًا دقيقًا قد يكشف روتينًا بوضوح مثل موقع. وأخيرًا، لا تفترض أن تقريرًا نظيفًا يعني صورة آمنة: قد تُظهر الصورة نفسها رقم شارع أو زيًا مدرسيًا أو لوحة سيارة. والبيانات الوصفية هي فقط نصف القصة.</p>\n<h2 id=\"comparing-photos\">مقارنة صورتين جنبًا إلى جنب</h2>\n<p>أحيانًا تقرير واحد لا يكفي: مقارنة صورتين تُظهر ما تغير بينهما، ما ينفع عندما يمر ملف عبر تطبيقات عدة.</p>\n<p>افتح الصورة الأولى وصدّر تقرير JSON واحفظ الملف. ثم نظف العارض بأيقونة سلة المهملات الحمراء وافتح الصورة الثانية بنفس الطريقة. وضع تقريري JSON جنبًا إلى جنب: أي حقل موجود في أحدهما وغائب في الآخر أضافه أو أزاله ما عالج الملف في المنتصف.</p>\n<p>هكذا يكتشف المطورون أي خطوة في سير عمل تزيل حقلًا. وهكذا يتعلم المصورون أي محرر يحتفظ ببيانات كاميرتهم وأيها يتخلص منها. واختبار شائع هو الأصل مقابل نسخة التواصل الاجتماعي: يُظهر الأصل EXIF وGPS كاملين، بينما نسخة منزلة من التواصل الاجتماعي لا تُظهر تقريبًا شيئًا. والفرق يثبت ما تفعله المنصة.</p>\n<p>واختبار مفيد آخر هو الأصل مقابل النسخة النظيفة: يجب أن تُظهر النسخة النظيفة الإشعار الأخضر بعدم وجود وسوم، بينما يُظهر الأصل الجدول الكامل. وذلك التباين هو دليلك على أن التنظيف نجح.</p>\n<h2 id=\"saving-reports\">حفظ التقارير لاحقًا</h2>\n<p>تقارير JSON المصدّرة تستحق العناء عندما تهم الصورة: تقرير ملف نصي صغير، سهل الحفظ بجانب الصورة أو في مجلد مشروع.</p>\n<p>احفظ تقارير لعمل العملاء، حيث قد يسأل عميل متى وأين التُقطت صورة: يجيب JSON على ذلك السؤال دون مشاركة الملف الأصلي. واحفظها أيضًا لتصحيح الأخطاء: عندما تتصرف صورة بغرابة بعد أشهر، يُظهر التقرير المحفوظ ما احتواه الملف قبل أي معالجة أخرى.</p>\n<p>سمِّ التقرير اسمًا واضحًا، مثل wedding-photo-metadata.json، لتستطيع إيجاده بعدها: الاسم الافتراضي يشمل بالفعل اسم ملف الصورة بلاحقة _metadata، وهو نمط جيد للاحتفاظ به.</p>\n<h2 id=\"how-to-view-summary\">ملخص سريع</h2>\n<p>افتح <a href=\"/ar/arid-bayanat-as-sura/\">عارض البيانات الوصفية</a> واسحب الملف الأصلي واقرأ إشعار الملخص أولًا. ثم راجع تنبيه GPS واستكشف الجدول المجمع ودوّن أي وسم Privacy Tag كهرماني.</p>\n<p>صدّر JSON إذا احتجت سجلًا: نظف الملف بـ<a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a> إذا ظهر شيء حساس، ثم أعد مراجعة النسخة النظيفة للتأكيد.</p>\n<p>الروتين كله يستغرق أقل من دقيقة: اجعله عادة قبل كل نشر، وستُظهر صورك فقط ما قررت مشاركته.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أرى البيانات الوصفية لصورة نشرتها عبر الإنترنت بالفعل؟","answer":"نزّل الصورة المنشورة أولًا ثم اسحب الملف المنزّل إلى العارض: معظم المنصات الاجتماعية تزيل البيانات الوصفية عند الرفع، فالنسخة المنزلة غالبًا لا تُظهر شيئًا، لكنها تستحق التحقق."},{"question":"هل يمكنني رؤية بيانات وصفية دون تثبيت أي برنامج؟","answer":"نعم، يعمل عارض البيانات الوصفية بالكامل في متصفحك: دون تثبيت ودون حساب ودون رفع ملفات. واسحب الملف واقرأ التقرير وأغلق التبويب: صورك لا تغادر جهازك أبدًا."},{"question":"ماذا أفعل إذا وجد العارض إحداثيات GPS في صورتي؟","answer":"لا تشارك ذلك الملف كما هو: افتح أداة إزالة البيانات الوصفية واسحب الصورة ونزّل النسخة النظيفة. ثم اسحب النسخة النظيفة مجددًا إلى العارض لتأكيد اختفاء تنبيه GPS."},{"question":"لماذا يُظهر العارض حقولًا مختلفة لنفس الصورة بصيغ مختلفة؟","answer":"كل صيغة تحفظ البيانات الوصفية بشكل مختلف: JPEG يحفظ أدلة EXIF وPNG يحفظ مقاطع نص وeXIf وWebP يحفظ مقاطع EXIF إضافة إلى علامات VP8X. وتحويل صورة بين الصيغ قد يغيّر الحقول التي تنجو."},{"question":"هل يمكنني رؤية البيانات الوصفية لصور كثيرة دفعة واحدة؟","answer":"يراجع العارض ملفًا واحدًا في كل مرة: لمراجعة دفعة، افحص كل ملف بالدور: انقر أيقونة سلة المهملات الحمراء في شريط الملخص لإعادة الضبط ثم اسحب الصورة التالية. وكل مراجعة تستغرق ثوانٍ."},{"question":"هل عرض البيانات الوصفية يغيّر صورتي بأي شكل؟","answer":"لا، العارض للقراءة فقط تمامًا: يقرأ الترويسات من ذاكرة المتصفح ويعرضها، دون تعديل أو ضغط أو حذف أي شيء من ملفك الأصلي. ويبقى ملفك على القرص كما كان بالضبط."}];
